import React from 'react';
import { useNavigate } from 'react-router-dom';
import GhostCursor from '../components/GhostCursor';

function LandingPage() {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-horror-black relative overflow-hidden">
      {/* Optimized Ghost Cursor - Reduced settings for smooth performance */}
      <GhostCursor
        color="#8b0000"
        brightness={0.9}
        edgeIntensity={0.1}
        trailLength={35}
        inertia={0.45}
        grainIntensity={0.03}
        bloomStrength={0.08}
        bloomRadius={0.8}
        bloomThreshold={0.03}
        fadeDelayMs={800}
        fadeDurationMs={1200}
        maxDevicePixelRatio={0.4}
        zIndex={5}
      />

      {/* Background Effects */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 blood-splatter opacity-20 animate-float"></div>
        <div className="absolute bottom-1/4 right-1/4 w-64 h-64 blood-splatter opacity-15 animate-float" style={{ animationDelay: '2s' }}></div>
      </div>

      {/* Main Content */}
      <div className="relative z-10 min-h-screen flex items-center justify-center px-4 bg-black">
        <button
          onClick={() => navigate('/app')}
          className="font-horror text-6xl md:text-8xl text-gray-300 text-glow tracking-wider cursor-pointer transition-all duration-500 hover:text-white hover:scale-110"
          style={{ textShadow: '0 0 20px rgba(255,255,255,0.3)' }}
        >
          AWAKE THE DEAD
        </button>
      </div>

      {/* Fog Effect */}
      <div className="fog"></div>
    </div>
  );
}

export default LandingPage;
